package com.sharehope.gallery.controller;import com.sharehope.gallery.model.GalleryItem;import com.sharehope.gallery.repository.GalleryRepository;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequiredArgsConstructor public class GalleryController{private final GalleryRepository repo;@GetMapping("/api/admin/gallery")public List<GalleryItem>list(){return repo.findAllByOrderByDisplayOrderAscCreatedAtDesc();}@PostMapping("/api/admin/gallery")@ResponseStatus(HttpStatus.CREATED)public GalleryItem create(@RequestBody GalleryItem item){item.setId(null);return repo.save(item);}@PutMapping("/api/admin/gallery/{id}")public GalleryItem update(@PathVariable UUID id,@RequestBody GalleryItem input){GalleryItem item=repo.findById(id).orElseThrow();item.setImageUrl(input.getImageUrl());item.setTitle(input.getTitle());item.setAltText(input.getAltText());item.setDisplayOrder(input.getDisplayOrder());item.setPublished(input.getPublished());return repo.save(item);}@DeleteMapping("/api/admin/gallery/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable UUID id){repo.deleteById(id);}@GetMapping("/api/public/gallery")public List<GalleryItem>publicList(){return repo.findAllByOrderByDisplayOrderAscCreatedAtDesc().stream().filter(GalleryItem::getPublished).toList();}}
